ns['finish'](c)
# Remap the prototype UVs into a continuous wood strip of the approved atlas.
for o in c.objects:
    if o.type!='MESH' or not o.data.uv_layers:continue
    if any(m.use_nodes and any(n.type=='TEX_IMAGE' for n in m.node_tree.nodes) for m in o.data.materials):
        for uv in o.data.uv_layers.active.data:
            u,v=uv.uv
            uv.uv=(.065+(u%1)*.012,.12+(v%1)*.48)
for m in bpy.data.materials:
