    bs=m.node_tree.nodes.get('Principled BSDF')
    tex=next((n for n in m.node_tree.nodes if n.type=='TEX_IMAGE' and n.image and 'Albedo' in n.image.name),None)
    if tex:m.node_tree.links.new(tex.outputs['Color'],bs.inputs['Base Color'])
bpy.ops.object.select_all(action='DESELECT')
